import type { ReactNode } from "react";
import { Sparkles } from "lucide-react";
import {serif} from "../../lib/constants"
export function SectionTitle({ children }: { children: ReactNode }) {
  return (
    <div className="mb-6 flex items-center justify-center gap-3">
      <h1 className={`${serif} m-0 mt-4 max-w-xl text-5xl font-[620] leading-[1.08] tracking-tight sm:text-6xl text-[var(--color-texto)]`}>
        {children}
      </h1>
    </div>
  );
}

{/*m-0  font-bold uppercase  font-[Georgia,'Times_New_Roman',serif]*/}