"use client";

import { useState } from "react";
import Image from "next/image";
import Link from "next/link";
import { Heart } from "lucide-react";
import { serif } from "../../lib/constants";
import type { Product } from "../../types";

type ProductCardProps = {
  product: Product;
  isNew?: boolean;
  onAdd: () => void;
};

export function ProductCard({ product, isNew, onAdd }: ProductCardProps) {
  const [saved, setSaved] = useState(false);

  return (
    <article className={`${serif} group flex h-full flex-col`}>
      {/* Imagen */}
      <Link href="/explorar" className="block">
        <div
          className={`relative aspect-[7/8] w-full overflow-hidden rounded-2xl bg-gradient-to-br ${product.tint}`}
        >
          {product.image && (
            <Image
              src={product.image}
              alt={product.name}
              fill
              sizes="(min-width: 1024px) 33vw, (min-width: 640px) 50vw, 100vw"
              className="object-cover transition duration-500 group-hover:scale-105"
            />
          )}

          {/* Etiquetas */}
          <div className="absolute left-3 top-3 flex items-center gap-2">
            <span className="rounded-md bg-[var(--color-primario)] px-3 py-1 text-[15px] font-medium leading-snug text-white">
              {product.category ?? product.store}
            </span>
            {isNew && (
              <span className="rounded-md bg-[var(--color-descuento)] px-3 py-1 text-[15px] font-medium leading-snug text-white">
                Nuevo
              </span>
            )}
          </div>

          {/* Guardar */}
          <button
            type="button"
            aria-label={`Guardar ${product.name}`}
            onClick={(event) => {
              event.preventDefault();
              setSaved((value) => !value);
            }}
            className="absolute right-3 top-3 flex h-9 w-9 items-center justify-center rounded-full bg-white/80 text-[#1b1b2f] backdrop-blur transition hover:text-[var(--color-descuento)]"
          >
            <Heart
              size={17}
              className={
                saved
                  ? "fill-[var(--color-descuento)] text-[var(--color-descuento)]"
                  : ""
              }
            />
          </button>
        </div>
      </Link>

      {/* Contenido */}
      <div className="flex flex-1 flex-col pt-4">
        <div className="flex items-baseline justify-between gap-3">
          <h3 className="truncate text-base text-[var(--color-texto)]">
            {product.name}
          </h3>
          <span className="shrink-0 text-base text-[var(--color-texto)]">
            ${product.price.toFixed(2)}
          </span>
        </div>

        {product.description && (
          <p className="mt-3 line-clamp-2 text-sm leading-snug text-[var(--color-texto-suave)]">
            {product.description}
          </p>
        )}

        <button
          type="button"
          onClick={onAdd}
          className="mt-auto w-full rounded-md border border-[var(--color-primario)] px-4 py-3.5 text-base font-semibold uppercase tracking-wide text-[var(--color-primario)] transition hover:bg-[var(--color-primario)] hover:text-white"
        >
          Agregar al carrito
        </button>
      </div>
    </article>
  );
}